const d = $input.first().json;
let arr = [];
try { arr = (typeof d.activities === 'string') ? JSON.parse(d.activities) : (d.activities || []); } catch (e) { arr = []; }
if (!Array.isArray(arr)) arr = [];
const names = arr.map(x => String(x || '').trim()).filter(Boolean);
return [{ json: { bot_id: d.bot_id, user_id: d.user_id, names } }];

const row = $input.first().json || {};
const names = $('Разобрать').first().json.names || [];
const asA = v => { if (v == null) return []; if (typeof v === 'string') { try { return JSON.parse(v); } catch (e) { return []; } } return v; };
const excl = asA(row.exclusions);
const lib = asA(row.library);
const exclTags = new Set(excl.filter(e => e.scope === 'load_tag').map(e => String(e.value).toLowerCase()));
const exclActs = new Set(excl.filter(e => e.scope === 'activity').map(e => String(e.value).toLowerCase()));
function findLib(name) { const n = name.toLowerCase(); let best = null; for (const a of lib) { const an = String(a.name).toLowerCase(); if (an === n) return a; const al = (a.aliases || []).map(x => String(x).toLowerCase()); if (al.includes(n)) return a; if (!best && (an.includes(n) || n.includes(an))) best = a; } return best; }
const results = names.map(nm => { const a = findLib(nm); if (!a) return { activity: nm, status: 'unknown' }; const tags = (a.tags || []).map(t => String(t).toLowerCase()); const badTags = tags.filter(t => exclTags.has(t)); const nameBad = exclActs.has(String(a.name).toLowerCase()); if (badTags.length || nameBad) return { activity: nm, status: 'blocked', reason: nameBad ? 'в списке запрещённых активностей' : ('нагрузка: ' + badTags.join(', ')) }; return { activity: nm, status: 'ok' }; });
const blocked = results.filter(r => r.status === 'blocked');
const unknown = results.filter(r => r.status === 'unknown');
const okList = results.filter(r => r.status === 'ok').map(r => r.activity);
let resp;
if (!excl.length) { resp = 'У клиента НЕТ активных ограничений — проверенные активности допустимы. Всё равно опирайся на здравый смысл и цель.'; }
else if (!blocked.length && !unknown.length) { resp = 'ДОПУСТИМЫ по ограничениям клиента: ' + names.join(', ') + '.'; }
else { const parts = []; if (blocked.length) parts.push('ЗАПРЕЩЕНЫ (убери из плана и замени на безопасное): ' + blocked.map(b => b.activity + ' [' + b.reason + ']').join('; ')); if (unknown.length) parts.push('НЕТ в библиотеке — проверь вручную по ограничениям клиента: ' + unknown.map(u => u.activity).join(', ')); if (okList.length) parts.push('Допустимы: ' + okList.join(', ')); resp = parts.join('. ') + '.'; }
return [{ json: { response: resp } }];
